  revision?: Prisma.RevisionOmit
  revisionHistory?: Prisma.RevisionHistoryOmit
  project?: Prisma.ProjectOmit
  userProjectProgress?: Prisma.UserProjectProgressOmit
  achievement?: Prisma.AchievementOmit
  userAchievement?: Prisma.UserAchievementOmit
  learningGoal?: Prisma.LearningGoalOmit
  learningActivity?: Prisma.LearningActivityOmit
  userQueueItem?: Prisma.UserQueueItemOmit
